 1→// Parsing is deliberately dumb: split, convert, and leave policy to combine().
 2→
 3→/** Split a line into its code and its count fields. */
 4→export function parseLine(line) {
 5→  const [code, ...fields] = line.trim().split(",");
 6→  return { code, fields };
 7→}
 8→
 9→/** Convert count fields to integers. A field that is not a number comes back NaN. */
10→export function parseCounts(fields) {
11→  return fields.map(parseInt);
12→}
